contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 dummy) public {
        require(dummy == 0);
        uint cBalBefore = address(c).balance;
        bool ok = c.setOwner(address(c)); if (__ESBMC_reverted()) return;
        assert(ok && c.owner() == address(c) && address(c).balance == cBalBefore);
    }
    receive() external payable {}
}

