pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function _run(uint256 dummy) internal {
        dummy = 0;
        uint cBalBefore = address(c).balance;
        bool ok;
        try c.setOwner(address(c)) returns (bool __r) { ok = __r; } catch { return; }
        assertTrue(ok && c.owner() == address(c) && address(c).balance == cBalBefore);
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
